use super::*;

/// Records in `doc` that an export would OVERWRITE WITH SOMETHING ELSE — a file-side edit the ledger
/// has never seen.
///
/// `doc` is the committed store as it is on disk. For each record in it:
///
/// - **not on main at all** — the files hold a record the ledger never saw. An export deletes it.
/// - **changed since it was exported** — the file no longer matches the body that was written to it,
///   so somebody edited the file. An export overwrites that edit.
/// - **never exported and already differing** — no watermark to compare against and the file does not
///   match the head either, so nothing can vouch for it.
///
/// A record whose file still matches what was last written is NOT drift, however far main has moved
/// since: that is the ledger being ahead, which is the direction the export exists to serve.
pub fn export_drift(conn: &Connection, doc: &Value) -> Result<Vec<Drift>, String> {
    let mut out = Vec::new();
    for (key, _tier) in [("implementations", TIER_IMPL), ("edges", TIER_EDGE)] {
        for rec in doc.get(key).and_then(Value::as_array).map(Vec::as_slice).unwrap_or(&[]) {
            let Some(id) = rec.get("id").and_then(Value::as_str) else { continue };
            let on_disk = import::body_of(rec);
            if get(conn, id)?.is_none() {
                out.push(Drift {
                    id: id.to_string(),
                    why: "the ledger has no record with this id — the export would DELETE the file"
                        .to_string(),
                });
                continue;
            }
            let mark: Option<i64> = conn
                .query_row("SELECT rev FROM exported WHERE id = ?1", params![id], |r| r.get(0))
                .ok();
            match mark {
                Some(rev) => {
                    let was = body_at(conn, id, rev)?;
                    if !was.as_ref().is_some_and(|w| same_body(w, &on_disk)) {
                        out.push(Drift {
                            id: id.to_string(),
                            why: format!(
                                "the file no longer matches what was written to it at rev {rev} — it was edited outside the ledger"
                            ),
                        });
                    }
                }
                // No watermark — an import from before watermarks existed, or a record another
                // session has written past. The HISTORY answers it: a file holding a body this ledger
                // has held was written by an export, not edited by hand.
                None if rev_holding(conn, id, &on_disk)?.is_none() => out.push(Drift {
                    id: id.to_string(),
                    why: "the file holds a body this ledger has never held — it was edited outside it"
                        .to_string(),
                }),
                None => {}
            }
        }
    }
    out.sort_by(|a, b| a.id.cmp(&b.id));
    Ok(out)
}
